import{_ as o,a0 as i,w as u,s as l,ao as n,I as a,x as r,a1 as s,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"DevOps 將去向何方？ | LCTT x X-CMD","titleTemplate":false,"description":"DevOps 將去向何方？ | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"DevOps 將去向何方？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"DevOps 將去向何方？ | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220902 Where is DevOps Headed-","title":"DevOps 將去向何方？","tag":"202210","desc":""},"relativePath":"202210/20220902 Where is DevOps Headed-.md","filePath":"[post].md"}'),d={name:"202210/20220902 Where is DevOps Headed-.md"};function b(O,e,v,D,h,m){const t=i("Link");return u(),l("div",null,[e[15]||(e[15]=n('<h1 id="devops-將去向何方" tabindex="-1">DevOps 將去向何方？ <a class="header-anchor" href="#devops-將去向何方" aria-label="Permalink to “DevOps 將去向何方？”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/07/DevOps.jpg" alt=""></p><blockquote><p>微軟、谷歌、亞馬遜、IBM 和甲骨文如今都在關注雲上的 DevOps。這些大公司正在給企業提供 IT 自動化的服務。然而，DevOps 仍然在持續的演進中。DevSecOps、AIOps 和 NoOps 正在成為下一個流行詞。</p></blockquote><p>隨着開發和管理人員看到及時交付高質量軟件的商業價值，<ruby>敏捷<rt>Agile</rt></ruby>方法論和 DevOps 也變得流行起來。擁有靈活的發佈週期，並且交付具有<ruby>可擴展<rt>scalable</rt></ruby>和<ruby>可定製<rt>customizable</rt></ruby>的軟件，是世界上每個企業的目標。通過將 CI/CD 工具和<ruby>管道<rt>pipeline</rt></ruby>部署到雲端，DevOps 使發佈過程變得更加流暢。融合了 DevOps 的 Polyglot 微服務架構正在幫助企業降低總擁有成本（TCO）。他們現在有能力用漸進式網絡應用程序和最新的 UI 框架升級他們的技術棧。總的來説，團隊正在以更好的效率執行任務，並且正在開發高質量的軟件模組。</p><h3 id="自治-devops" tabindex="-1">自治 DevOps <a class="header-anchor" href="#自治-devops" aria-label="Permalink to “自治 DevOps”">​</a></h3><p>容器和 DevOps 與雲原生應用走到了一起。Kubernetes 和 Docker 正在被用作容器，一個新的名詞 NoOps 現在正在流行。對於不同的容器，<ruby>編排<rt>Orchestration</rt></ruby>都是一個重要的功能。為了擴展應用，開發環境中要創建容器集羣。有一些新的容器正在進入雲原生應用這個領域，比如 Mesos、Swarm、Openshift Rancher 和 Nomad。NoOps 有助於縮短編碼週期，從而監控和管理應用程序。缺陷修復和熱修復是不同的活動，它們都是 NoOps 的一部分。NoOps 有助於提高技術團隊和業務運營人員之間的協同作用。它也有助於更好的監控、管理和流程自動化。NoOps 基礎設施能夠控制應用程序在雲上的部署。企業從中獲得的好處包括更好的交付、彈性的服務、更快的發佈、良好的質量和 CI/CD 自動化。</p><h3 id="devsecops" tabindex="-1">DevSecOps <a class="header-anchor" href="#devsecops" aria-label="Permalink to “DevSecOps”">​</a></h3><p>DevSecOps 算是另一個流行趨勢，它與在開發操作中的安全問題有關。最近與<ruby>漏洞<rt>vulnerabilities</rt></ruby>（log4j），<ruby>安全泄露<rt>security breach</rt></ruby>（谷歌、臉書、微軟），和安全攻擊相關的問題增加了 DevSecOps 在企業中的重要性。<ruby>左移<rt>shift left</rt></ruby>方法強調了在軟件生命週期的早期處理安全性和質量的重要性。在架構階段就需要考慮隱私和<ruby>遵從性<rt>compliances</rt></ruby>（如 GDPR）。這有助於降低成本，並且提升軟件交付的速度。審計工具和安全檢查列表是 DevOps 工具和系統的一部分，現在我們稱為 DevSecOps。</p><h3 id="aiops" tabindex="-1">AIOps <a class="header-anchor" href="#aiops" aria-label="Permalink to “AIOps”">​</a></h3><p>AI DevOps 現在被稱為 AIOps。據預測，將來 AI 應用會由 AIOps 來管理。與 AIOps 相關的工具和軟件正在開發中，並且將很快發佈首個版本。AI/ML 應用部署和模型更新可以由 AIOps 來處理。這將在<ruby>工業 4.0<rt>Industry 4.0</rt></ruby> 以及數據科學中扮演重要角色。有一種觀點認為，NoOps 將會是 AIOps 的最終形態。AIOps 包括數據集管理、模型訓練、模型服務、元數據管理、模型更新和服務更新。分佈式訓練將由 AIOps 來完成，這會提供<ruby>超參數<rt>hyper parameter</rt></ruby>優化，工作流程管理和“<ruby>假設<rt>what if</rt></ruby>”的分析能力。</p><h3 id="微服務配置管理" tabindex="-1">微服務配置管理 <a class="header-anchor" href="#微服務配置管理" aria-label="Permalink to “微服務配置管理”">​</a></h3><p>當前，DevOps 和微服務正在成為標準部署和<ruby>架構藍圖<rt>architectural blueprints</rt></ruby>來實施。應用可以在模組級別上就進行擴展。微服務可以在簡化缺陷修復和問題區域隔離上提供幫助。經過設計，微服務可以通過添加更多<ruby>計算能力<rt>computing power</rt></ruby>的<ruby>實例<rt>instances</rt></ruby>來進行擴展。但是當它們沒有被正確實現的時候，數據安全和管理的問題就會突然出現。</p><h3 id="平台即產品" tabindex="-1">平台即產品 <a class="header-anchor" href="#平台即產品" aria-label="Permalink to “平台即產品”">​</a></h3><p>雲上的<ruby>軟件即服務<rt>Software as a Service</rt></ruby>和<ruby>平台即產品<rt>Platform as a Product</rt></ruby>最近非常流行。通過加速向平台部署和功能交付，DevOps 使這些變成現實。從編碼到上線階段，CI/CD 管道有助於可視化應用的部署。持續交付、集成和部署都是 DevOps 的一部分。DevOps 生產線模擬工業生產線是未來要關注的。</p><p>DevOps 正在慢慢地向 DevSecOps 和 AIOps 轉變。對於企業，NoOps 才是未來。現在需要的是減少與安全相關的攻擊、事故和破壞發生。對於企業來説，數據安全和隱私的優先級更高，並且這些新技術都將在這方面有所幫助。</p><hr>',16)),a("p",null,[e[1]||(e[1]=r("via: ",-1)),s(t,{href:"https://www.opensourceforu.com/2022/09/where-is-devops-headed/"},{default:p(()=>[...e[0]||(e[0]=[r("https://www.opensourceforu.com/2022/09/where-is-devops-headed/",-1)])]),_:1})]),a("p",null,[e[6]||(e[6]=r("作者：",-1)),s(t,{href:"https://www.opensourceforu.com/author/bhagvan-kommadi/"},{default:p(()=>[...e[2]||(e[2]=[r("Bhagvan Kommadi",-1)])]),_:1}),e[7]||(e[7]=r(" 選題：",-1)),s(t,{href:"https://github.com/lkxed"},{default:p(()=>[...e[3]||(e[3]=[r("lkxed",-1)])]),_:1}),e[8]||(e[8]=r(" 譯者：",-1)),s(t,{href:"https://github.com/Yufei-Yan"},{default:p(()=>[...e[4]||(e[4]=[r("Yufei-Yan",-1)])]),_:1}),e[9]||(e[9]=r(" 校對：",-1)),s(t,{href:"https://github.com/wxy"},{default:p(()=>[...e[5]||(e[5]=[r("wxy",-1)])]),_:1})]),a("p",null,[e[12]||(e[12]=r("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[10]||(e[10]=[r("LCTT",-1)])]),_:1}),e[13]||(e[13]=r(" 原創編譯，",-1)),s(t,{href:"https://linux.cn/"},{default:p(()=>[...e[11]||(e[11]=[r("Linux中國",-1)])]),_:1}),e[14]||(e[14]=r(" 榮譽推出",-1))])])}const I=o(d,[["render",b]]);export{T as __pageData,I as default};
